import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define CUDA kernel for matrix multiplication with optimized shared memory
matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define PAD 1  // Padding to avoid bank conflicts

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory with padding to avoid bank conflicts
    __shared__ float As[TILE_SIZE][TILE_SIZE + PAD];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE + PAD];

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tile from A into shared memory (coalesced access)
        int load_row = row;
        int load_col = t * TILE_SIZE + threadIdx.x;
        if (load_row < N && load_col < N) {
            As[threadIdx.y][threadIdx.x] = A[load_row * N + load_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile from B into shared memory (coalesced access)
        load_row = t * TILE_SIZE + threadIdx.y;
        load_col = col;
        if (load_row < N && load_col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[load_row * N + load_col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial product with unrolled loop
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; k++) {
            sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
