import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define CUDA kernel for matrix multiplication with register blocking
matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 64
#define SUB_TILE 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory tiles
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Block indices
    int bx = blockIdx.x * TILE_SIZE;
    int by = blockIdx.y * TILE_SIZE;

    // Each thread computes a 4x4 sub-tile of C
    float c[SUB_TILE][SUB_TILE] = {{0}};

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tile from A into shared memory (coalesced access)
        int load_x = t * TILE_SIZE + tx;
        int load_y = by + ty;
        if (load_y < N && load_x < N) {
            As[ty][tx] = A[load_y * N + load_x];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile from B into shared memory (coalesced access)
        load_x = bx + tx;
        load_y = t * TILE_SIZE + ty;
        if (load_y < N && load_x < N) {
            Bs[ty][tx] = B[load_y * N + load_x];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial products using register blocking
        for (int k = 0; k < TILE_SIZE; k++) {
            // Prefetch values to registers
            float a_val = As[ty][k];
            float b_val = Bs[k][tx];

            // Update all 4x4 elements in registers
            for (int i = 0; i < SUB_TILE; i++) {
                for (int j = 0; j < SUB_TILE; j++) {
                    c[i][j] += a_val * b_val;
                }
            }
        }

        __syncthreads();
    }

    // Write results to global memory
    for (int i = 0; i < SUB_TILE; i++) {
        for (int j = 0; j < SUB_TILE; j++) {
            int row = by + ty * SUB_TILE + i;
            int col = bx + tx * SUB_TILE + j;
            if (row < N && col < N) {
                C[row * N + col] = c[i][j];
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Check inputs
    TORCH_CHECK(A.dim() == 2, "A must be a matrix");
    TORCH_CHECK(B.dim() == 2, "B must be a matrix");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions mismatch");
    TORCH_CHECK(A.device().is_cuda() && B.device().is_cuda(), "Inputs must be on CUDA");

    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    // Configure kernel launch parameters
    dim3 threads(16, 16);  // 16x16 = 256 threads per block
    dim3 blocks((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    // Launch kernel
    matmul_kernel<<<blocks, threads>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

matmul_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

# Load the CUDA extension
matmul_extension = load_inline(
    name="matmul_extension",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_kernel_source,
    functions=["matmul_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return matmul_extension.matmul_cuda(A, B)"}

